            if key==ROOT.."rate:"..p.reservation.v[kind.."_scope_id"] and rate_fields[field] then return field=="updated_at_ms" and "time" or "counter" end
        end end
    end
    for _,call in ipairs(calls) do
        local p,a=call.effect_policy,call.argv
