    calls[#calls+1] = {"ZADD",run.key .. ":" .. v.state,at,v.job_id}
    if v.state == "ready" then calls[#calls+1] = {"ZADD",run.key .. ":ready_at",ctx.now_text,v.job_id}; indexes.ready_at = 1 end
