    -- must correspond to the fixed contiguous slices required by the norm.
    for _,kind in ipairs({"outlinks","discoveries"}) do
        local count=0
        for ordinal=0,(kind=="outlinks" and 3 or 1) do
            if v[kind.."_chunk_"..decimal(ordinal).."_digest"]~="" then
